html:
{%- set g = get_ghs_label_data(doc.name) -%}
<style>
	.print-format { page-width: 101.6mm; page-height: 50.8mm; margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; padding: 0 !important; width: 101.6mm !important; max-width: 101.6mm !important; min-height: 0 !important; }
	.ghs { box-sizing: border-box; width: 101.6mm; height: 50.6mm; padding: 1.6mm 2mm 1.2mm 2mm; overflow: hidden; position: relative; font-family: Arial, Helvetica, sans-serif; color: #000; background: #fff; page-break-after: always; }
	.ghs table { border-collapse: collapse; width: 100%; }
	.ghs td { padding: 0; vertical-align: top; }
	.ghs .hdr td { vertical-align: middle; border-bottom: 0.4mm solid #000; padding-bottom: 0.6mm; }
	.ghs .pname { font-size: 9pt; font-weight: bold; line-height: 1.05; }
	.ghs .pref { font-size: 5.5pt; font-weight: normal; }
	.ghs .signal { text-align: right; font-size: 13pt; font-weight: 900; letter-spacing: 0.3pt; white-space: nowrap; padding-left: 2mm; }
	.ghs .picts { padding: 0.8mm 1.2mm 0 0; }
	.ghs .picts td { padding: 0 0.3mm 0.3mm 0; }
	.ghs .picts img { display: block; }
	.ghs .stmts { padding-top: 0.8mm; line-height: 1.12; }
	.ghs .stmts b { font-weight: bold; }
	.ghs .stmts .h { display: block; }
	.ghs .ftr { position: absolute; left: 2mm; bottom: 1.2mm; width: 97.6mm; border-top: 0.3mm solid #000; font-size: 5.2pt; line-height: 1.15; padding-top: 0.5mm; }
	.ghs .ftr .r { text-align: right; white-space: nowrap; padding-left: 1.5mm; }
	.ghs .missing { border: 0.5mm solid #c00; color: #c00; padding: 1.5mm; font-size: 7pt; }
	.ghs .missing ul { margin: 0.5mm 0 0 3.5mm; padding: 0; }
</style>
<div class="ghs">
{%- if g.missing -%}
	<div class="missing">
		<b>{{ _("GHS label not printed: this SDS record is missing required label elements.") }}</b>
		<div style="color:#000; margin-top:0.5mm">{{ doc.name }} {{ doc.product_name or "" }}</div>
		<ul>{%- for m in g.missing -%}<li>{{ m }}</li>{%- endfor -%}</ul>
	</div>
{%- else -%}
	<table class="hdr">
		<tr>
			<td class="pname">{{ doc.product_name }}{% if doc.product_reference_number %}<div class="pref">{{ doc.product_reference_number }}</div>{% endif %}</td>
			{%- if g.signal -%}<td class="signal">{{ g.signal | upper }}</td>{%- endif -%}
		</tr>
	</table>
	<table>
		<tr>
			{%- if g.pictograms -%}
			<td class="picts" style="width:{{ (g.picto_in * g.picto_cols) + 0.08 }}in">
				<table style="width:auto">
				{%- for row in g.pictograms | batch(g.picto_cols) -%}
					<tr>{%- for p in row -%}<td><img src="{{ p.src }}" alt="{{ p.code }}" style="width:{{ g.picto_in }}in; height:{{ g.picto_in }}in"></td>{%- endfor -%}</tr>
				{%- endfor -%}
				</table>
			</td>
			{%- endif -%}
			<td class="stmts" style="font-size:{{ g.font_pt }}pt">
				{%- if g.hazards -%}
				{%- for h in g.hazards -%}<span class="h">{{ h }}</span>{%- endfor -%}
				{%- endif -%}
				{%- if g.precautions -%}
				<div style="margin-top:0.6mm"><b>{{ _("Precautions:") }}</b> {{ g.precautions | join(" ") }}</div>
				{%- endif -%}
				{%- if not g.hazardous -%}<div>{{ _("Not classified as hazardous under GHS. See SDS for handling information.") }}</div>{%- endif -%}
			</td>
		</tr>
	</table>
	<table class="ftr">
		<tr>
			<td>
				<b>{{ doc.manufacturer_name }}</b>, {{ g.address }}<br>
				{%- if doc.man_phone -%}{{ _("Tel") }} {{ doc.man_phone }}{%- endif -%}
				{%- if doc.man_phone and doc.emergency_phone %} &nbsp;|&nbsp; {% endif -%}
				{%- if doc.emergency_phone -%}<b>{{ _("Emergency") }} {{ doc.emergency_phone }}</b>{%- endif -%}
			</td>
			<td class="r">
				{{ doc.name }}{% if doc.version_date %}<br>{{ _("SDS rev") }} {{ frappe.format(doc.version_date, {"fieldtype": "Date"}) }}{% endif %}<br>
				<b>{{ _("Read the SDS before use") }}</b>
			</td>
		</tr>
	</table>
{%- endif -%}
</div>
